#include <iostream>
#include <string>
using namespace std;

void winners(string customers[], int size, int lucky, int luckycache) {
        lucky--;
        for(int i = 0; i < size; i++)
        {
            if(lucky > (size-1))
            {
                break;
            }
            cout<<customers[lucky]<<endl;
            lucky = lucky + luckycache; 
        }
    
}

int main() {

    int luckycache;
    string customers[] = {"Alice", "Bob", "Rayan", "Emma", "Ann", "Bruce", "Synthia", "Daniel", "Richard", "Sam", "Nick", "Mary", "Paul"};

    int n;
    cin >> n;
    luckycache = n;
    winners(customers, 13, n, luckycache);
    
    return 0;
}
